    if (stranded.length === 0) {
        return {
            name: "Resource Discovery",
            didPass: true,
            message: `All resources are covered by discovery.paths ${JSON.stringify(patterns)}`,
        };
    }
    const list = stranded
        .map((resource) => normalize(relative(projectRoot, resource.path)))
        .join(", ");
